T.forEach(t => Object.assign(t.loc, X2[t.id] || {}));
const G = [["Ascending", "a"], ["Descending", "d"], ["Both", "b"], ["Cranial nerves", "n"]], AR = { a: "▲", d: "▼", b: "⇅", n: "◆" }, LN = { a: "Ascending", d: "Descending", b: "Ascending + descending", n: "Cranial nerve (nuclei shown in the sections; dashes trace conduction)" };
const SEC = [["cx", "Cerebral cortex, left lateral view: higher-order areas"], ["th", "Thalamic nuclei and basal ganglia (composite coronal schematic)"], ["rmb", "Rostral midbrain: superior colliculus, red nucleus"], ["cmb", "Caudal midbrain: inferior colliculus, ventral tegmental decussation"], ["rp", "Rostral pons"], ["cp", "Caudal pons: trapezoid body"], ["cbl", "Cerebellum: cortex, deep nuclei and peduncles (schematic)"], ["rm", "Rostral medulla: olive, open 4th ventricle"], ["mm", "Mid medulla: sensory decussation"], ["cm", "Caudal medulla: pyramidal decussation"], ["c", "Cervical spinal cord"]];
